package com.arcvision.arcledger.data.dao; import android.content.*; import android.database.Cursor; import com.arcvision.arcledger.data.db.DatabaseHelper; import com.arcvision.arcledger.data.model.Supplier; import java.util.*; public class SupplierDao {private final DatabaseHelper h; public SupplierDao(Context c){h=new DatabaseHelper(c);} public List<Supplier> getAllSuppliers(){Cursor c=h.getReadableDatabase().rawQuery("SELECT * FROM suppliers",null);List<Supplier> l=new ArrayList<>();while(c.moveToNext()){Supplier x=new Supplier();x.id=c.getLong(0);x.name=c.getString(1);x.phone=c.getString(2);l.add(x);}c.close();return l;}}
